"""Açıklamalı, kaynak izli emisyon / imisyon soru bankası."""
import json
import re
from pathlib import Path
from quiz_primary import extend
from quiz_en import extend as extend_en
from quiz_advanced import extend as extend_advanced
from quiz_review import extend as extend_review

ROOT=Path(__file__).resolve().parents[1]
catalog={}
for f in ('standards.json','standards_extra.json','standards_overrides.json'):
    for x in json.loads((ROOT/'assets'/f).read_text(encoding='utf-8')):catalog[x['code']]=x
questions=[]


def parameters(tags):
    mapping=[('14789','O₂'),('14792','NOₓ'),('15058','CO'),('12341','PM10 / PM2,5'),('2341','Çöken toz'),
      ('2342','Çöken toz'),('Pasif','Pasif örnekleme'),('Method 4','Nem'),('Method 13A','Flor / florür'),
      ('Method 26A','Klor / halojenler'),('1911','HCl'),('Method 29','Ağır metaller'),('14385','Ağır metaller'),
      ('11338','PAH'),('1948','Dioksin / furan'),('426','Siyanür / HCN'),('425','Krom(VI)'),('323','Formaldehit'),
      ('CTM 027','Amonyak'),('207.1','Amonyak'),('Method 11','H₂S'),('Method 8','Sülfürik asit / SO₂'),
      ('7935','SO₂'),('CTM-022','NOₓ'),('13649','VOC'),('12619','TOC / FID'),('25A','TOC / FID'),
      ('12039','Yanma gazları'),('16911','Hız / debi'),('10780','Hız / debi'),('Method 2','Hız / debi'),
      ('15259','Ölçüm yeri / travers'),('Method 1','Ölçüm yeri / travers'),('9503','İslilik'),('ISDL','ISDL / MID'),
      ('13284','Partikül madde'),('9096','Partikül madde'),('12141','Partikül madde'),('Method 5','Partikül madde'),('Method 17','Partikül madde')]
    result=set()
    for tag in tags:
        for needle, parameter in mapping:
            if re.search(re.escape(needle)+r'(?![0-9A-Za-z])',tag):
                result.add(parameter)
                break
    return sorted(result) or ['Genel saha']


def add(topic, scope, tags, prompt, right, wrong, explanation, source):
    standards=[code for code in catalog if any(re.search(re.escape(tag)+r'(?![0-9A-Za-z])',code) for tag in tags)]
    assert len(wrong)==3 and len(set([right,*wrong]))==4
    questions.append(dict(id=f'q{len(questions)+1:03}',topic=topic,scope=scope,parameters=parameters(tags),standards=standards,
        prompt=prompt,choices=[right,*wrong],correctIndex=0,explanation=explanation,source=source))


T='İmpinger ve özel metotlar'; E='Emisyon'; I='İmisyon'; O='Ortak'
