add(T,E,['EPA Method 4'],'EPA Method 4’te silika jel çıkış sıcaklığı için hangi koşul aranır?','20 °C altında',['120 °C üstünde','Tam 42 °C','Ortam sıcaklığıyla daima aynı'],'Buz-su banyosu kullanılarak silika jel çıkışı 20 °C altında tutulur. Probun yaklaşık 120 °C olması başka bir sensör ve başka bir amaçla ilgilidir.','D08:4,6')
add(T,E,['EPA Method 4'],'EPA Method 4’te son kaçak sınırı hangisidir?','Ortalama debinin %4’ü ile 0,57 L/dk değerinden küçük olanı',['Her koşulda 0,57 L/dk','İki değerden büyük olanı','Her koşulda debinin %10’u'],'Sınır iki koşuldan daha sıkı olanıdır. Küçük debide yalnız 0,57 L/dk sınırını kullanmak aşırı kaçağı kabul edebilir.','D08:5')
add(T,E,['EPA Method 4'],'EPA Method 4’te 0,60 scm asgari hacmi Türkçe arayüzde nasıl korunmalıdır?','Kaynağın referans koşullarında 0,60 standart m³',['Her durumda 0 °C’de 0,60 Nm³','Ham DGM’de mutlaka 0,60 m³','Baca koşullarında mutlaka 600 L'],'Hacim birimi ile gazın referans koşulu farklıdır. DGM, baca koşulları ve standart koşullardaki hacimler birbirinin yerine kullanılamaz.','D08:4; ortak saha esasları: referans koşulları')
add(T,E,['EPA Method 13A'],'EPA Method 13A ana düzeninde filtre nerededir?','Üçüncü ve dördüncü impinger arasında',['Daima tüm impingerlerden sonra','İkinci şişenin sıvısının içinde','Pompanın egzozunda'],'Arşiv §8.3 bu düzeni verir; uygun destek koşuluyla prob–ilk impinger arasında alternatif de vardır. Filtre konumu kayıt altına alınır.','D05:2,5')
add(T,E,['EPA Method 13A'],'EPA Method 13A için örnekleme debisi hangi koşulu sağlar?','İzokinetik ve 28 L/dk altında',['Her bacada sabit 28 L/dk','En az 28 L/dk','Yalnız 2 L/dk'],'28 L/dk bir üst sınırdır; cihazı her noktada 28 L/dk’ye ayarlama talimatı değildir. İzokinetik koşul korunmalıdır.','D05:5')
add(T,E,['EPA Method 13A'],'EPA Method 13A ön filtre alternatifinde hangi ayrıntı önemlidir?','20-mesh paslanmaz filtre desteği koşulu',['Cam fritin her durumda zorunlu oluşu','Filtrenin mutlaka tartılmış olması','Filtrenin silika jel yerine kullanılması'],'Metot, ön filtre ile üçüncü/dördüncü şişe arası filtre için farklı tutucu/destek koşulları belirtir. Yalnız filtreyi taşımak yeterli değildir.','D05:2,5')
add(T,E,['EPA Method 26A'],'EPA Method 26A’da isteğe bağlı kondensat şişesi kullanılırsa başlangıç içeriği nedir?','50 mL 0,1 N H₂SO₄',['100 mL 0,1 N NaOH','200 mL su','200 g silika jel'],'Kondensat tutucu opsiyoneldir. Sonraki iki asit şişesinin her birindeki 100 mL dolumla karıştırılmamalıdır.','D06:4,6')
add(T,E,['EPA Method 26A'],'EPA Method 26A asit ve alkali fraksiyonları geri alınırken doğru yaklaşım nedir?','Ayrı fraksiyonlar halinde korunur.',['Hepsi tek kaba birleştirilir.','Asit fraksiyonu atılır.','Alkali fraksiyonu silika jelle karıştırılır.'],'Hidrojen halojenür ve halojen toplama fraksiyonları farklıdır. Birleştirmek yöntemin analitik ayrımını bozar.','D06:8')
add(T,E,['EPA Method 26A'],'EPA Method 26A standart prob/filtre ısıtma aralığı hangisidir?','120–134 °C',['0–20 °C','42–60 °C','Her bacada baca sıcaklığı kadar'],'Bu aralık, incelenen kaynakta prob ve filtre çevresi içindir. İlgili alt düzenleme veya yetkili onayındaki istisnalar ayrıca kontrol edilir.','D06:4,6-7')
add(T,E,['EPA Method 29'],'EPA Method 29’da cıva analizi yapılmayacaksa hangi şişeler gerekmeyebilir?','Metot şemasındaki 4, 5 ve 6',['Her zaman 2 ve 3','Yalnız silika jel şişesi','Bütün şişeler'],'§8.1.3.3 cıva için eklenen bu üç şişeyi kaldırma olanağı verir. Cıvasız düzenin yine diğer metal fraksiyonlarını toplaması gerekir.','D07:11')
add(T,E,['EPA Method 29'],'EPA Method 29’da ilk boş şişenin çıkarılması neye bağlıdır?','Toplanacak nemin yaklaşık 100 mL’den az olmasına ve metot koşullarına',['Cihaz markasına','Her ölçümün 30 dakika olmasına','Yalnızca operatör tercihine'],'İlk kondensat şişesinin kaldırılması koşulsuz değildir. Bu seçenek, cıva ek şişelerinin kaldırılmasıyla aynı karar değildir.','D07:11')
add(T,E,['EPA Method 29'],'EPA Method 29’da ikinci ve üçüncü impingerin her birine ne konur?','100 mL HNO₃/H₂O₂ absorbanı',['100 mL asitli permanganat','50 mL NaOH','Yalnız saf su'],'İkinci/üçüncü şişeler metal toplama asitli peroksit fraksiyonudur. Cıva için asitli permanganat farklı şişelerde yer alır.','D07:11')
add(T,E,['EPA Method 29'],'EPA Method 29 cıva düzeninde peroksit ve permanganat için hangi yaklaşım doğrudur?','Ayrı tutulur; birbirine karıştırılmaz.',['Ölçümden önce eşit hacimde karıştırılır.','Tek ortak blank yeterli sayılır.','Mangan analizi için permanganat her yere sürülür.'],'Metot hem kimyasal reaksiyon hem de Mn bulaşması nedeniyle fraksiyon ayrımını vurgular. Ortak kaba toplama güvenilir geri kazanım değildir.','D07:11,13-14')
add(T,E,['EPA Method 8'],'EPA Method 8’de filtre nereye yerleştirilir?','Birinci ve ikinci impinger arasına; ısıtılmaz.',['Prob ile ilk şişe arasına; her zaman 180 °C','Dördüncü şişeden sonra; ısıtılır.','İlk şişenin içine tamamen daldırılır.'],'Method 8’in filtre yeri Method 5 ile aynı değildir. Özel sıra, toplanan fraksiyonların ayrılması için önemlidir.','D10:2')
add(T,E,['EPA Method 8'],'EPA Method 8 ilk impingerinin dolumu hangisidir?','100 mL %80 izopropanol',['100 mL %3 H₂O₂','200 mL 0,1 N NaOH','Başlangıçta boş'],'İkinci ve üçüncü şişeler %3 H₂O₂ içerir. İlk şişenin içeriğini sonraki şişelerle karıştırmak yöntem seçiciliğini bozar.','D10:4')
add(T,E,['EPA Method 8'],'EPA Method 8’de 15 dakikalık temiz hava geçirme işlemi ne zaman yapılır?','Örneklemeden sonra, prob ayrılarak kalan trenden',['Ana örnekleme başlamadan tüm saha süresi yerine','Numune yerine bacaya ters yönde','Yalnız DGM kalibrasyonu sırasında'],'Bu işlem ana örnekleme süresinden ayrı bir ölçüm sonrası aşamadır. Kaynakta örnekleme ortalama debisinde 15 dakika belirtilir.','D10:5')
add(T,E,['TS EN 1948-1'],'EN 1948-1:2006 filtre/yoğuşturucu yönteminde filtre sıcaklığı nasıl olmalıdır?','Çiy noktasının üstünde ve 125 °C altında',['Her zaman 180 °C','Çiy noktasının altında','Daima 20 °C altında'],'Filtrede istenmeyen yoğuşma ve sıcaklıkta oluşabilecek reaksiyonlar birlikte kontrol edilir. Yoğuşturucu sonrası <20 °C koşulu farklı noktaya aittir.','D25:15,22')
add(T,E,['TS EN 1948-1'],'EN 1948-1 arşiv metnindeki saha blankında gaz çekişi nasıl olur?','Gaz çekilmez; kurulum ve kaçak testi yapılır.',['Üç saat baca gazı çekilir.','Prob mutlaka bacaya sokulur.','Kaçak testi de kesinlikle yapılmaz.'],'§7.3 blankın aynı sahada kurulmasını, probun bacaya sokulmamasını ve gaz çekilmemesini tarif eder. Bu kural tüm başka metot blanklarına otomatik uygulanmaz.','D25:21')
add(T,E,['TS EN 1948-1'],'EN 1948-1:2006’da numune saklama için incelenen koşul hangisidir?','Karanlıkta, yaklaşık 25 °C oda sıcaklığını aşmadan',['Güneşte, 60 °C’de','Her durumda −80 °C’de','Ağzı açık, havalandırılarak'],'Arşiv §9.3.5.2 bu koşulu ve teslim zincirini ister. Bu sorunun cevabı PAH standardının saklama koşuluna kopyalanamaz.','D25:25')
add(T,E,['TS ISO 11338'],'ISO 11338-1 Metot B’de yoğuşturucu sonrası gaz sıcaklığı ne olmalıdır?','20 °C altında',['125 °C üstünde','Baca sıcaklığıyla aynı','Sadece ortamdan 10 °C yüksek'],'Metot B filtre sonrasında gazı soğutup gaz fazı PAH’ları adsorban/absorbanla toplar. Filtre ve yoğuşturucu aynı sıcaklıkta çalıştırılmaz.','D27:13-14')
add(T,E,['TS ISO 11338'],'PAH düzeneğinde izokinetik debi adsorban için fazla yüksekse ne değerlendirilir?','Doğrulanmış akış bölünmesi ve ayrı ana/yan kol ölçümü',['Kartuşun sınırını dikkate almadan bütün gazı geçirmek','Ana kol hacmini rastgele yarıya indirmek','Yoğuşturucuyu kaldırmak'],'ISO 11338-1, akış bölünmesinin yakalama verimi amacıyla kullanılabileceğini açıklar. Ana kol ve yan kol hacimleri ölçülmeli; birbirinin yerine geçmemelidir.','D27:13-14')
add(T,E,['TS EN 1911'],'TS EN 1911’de HCl olarak ifade edilen gaz klorürler, Cl₂ ile aynı parametre midir?','Hayır; parametre ve metot kapsamları ayrıdır.',['Evet, bütün koşullar ve sonuçlar özdeştir.','Yalnız birim harfi farklıdır.','İkisi de sadece toplam metal yöntemidir.'],'Gaz halindeki klorürün HCl olarak raporlanması elementel klorla özdeş değildir. Kimyasal tür ve fraksiyon ayrımı doğru metot seçiminin parçasıdır.','D53:5; D06:4,8')
add(T,E,['CARB Method 426'],'TL115 aktarımındaki HCN düzeninde ilk iki şişenin her birindeki dolum nedir?','100 mL 0,1 N NaOH',['100 mL %80 izopropanol','50 mL H₂SO₄','200 g silika jel'],'Bu miktar TL115 §5.4.1.3 kaynaklıdır. Birincil CARB 426 doğrulaması henüz tamamlanmamıştır; soru güncel tüm sürümler adına evrensel koşul iddia etmez.','D41:6 — talimat kaynaklı')
add(T,E,['CARB Method 426'],'HCN talimatında yazan 500 mL numune miktarı neyle karıştırılmamalıdır?','Çekilen gazın toplam hacmiyle',['Numune kabındaki sıvı miktarıyla','Teslim edilen örnek miktarıyla','Laboratuvar numune miktarıyla'],'Sıvı numune miktarı ile örneklenen gaz hacmi farklı boyutlardadır. 500 mL sıvı bilgisi gaz çekişini 0,5 L yapma talimatı değildir.','D41:7')
add(T,E,['TS EN 14385'],'TS EN 14385 metal çalışmasında cıva da istenirse doğru ilk adım nedir?','Cıvanın seçilen metodun kapsamında olup olmadığını ve uygun yöntemi kontrol etmek',['Mevcut trene rastgele permanganat eklemek','Bütün metal sonuçlarını cıva kabul etmek','Sadece filtre renginden cıva hesaplamak'],'Cıva diğer metallere göre farklı toplama fraksiyonları gerektirebilir. TL179 da cıva için EPA 29 düzenine yönlendirir; farklı metotların parçaları doğrulanmadan birleştirilmez.','D47:5-6 — kapsam / talimat karşılaştırması')
add(T,E,['CARB Method 425'],'Krom(VI) ölçümü ile toplam krom ölçümü için hangisi doğrudur?','Aynı analit tanımı değildir; türleşme ve numune koruması önemlidir.',['Her zaman aynı sayısal sonucu verir.','Toplam metal filtresi görünümü yeterlidir.','Krom(VI), yalnızca gaz debisinin adıdır.'],'Kromun oksidasyon basamağının korunması türleşme ölçümünün temelidir. Toplam metal miktarından otomatik Krom(VI) üretilemez; ayrıntılı CARB 425 koşulları ayrıca doğrulanır.','D17:12-19 — eğitim / kavramsal')
add(T,E,['EPA CTM 027','SCAQMD Method 207.1'],'Amonyak için CTM 027 ile SCAQMD 207.1 bilgileri nasıl kullanılmalıdır?','Her metodun kendi ekipman, debi ve fraksiyon koşulları ayrı korunur.',['Biri süre, diğeri çözelti seçilerek rastgele birleştirilir.','İsim farkı dışında her ayrıntı aynıdır.','Her ikisine de HCN reçetesi atanır.'],'Aynı parametreyi hedeflemek metotların bütün koşullarını eşitlemez. Reçete ve debi, belirli düzenek ve metot sürümüyle birlikte seçilmelidir.','D17:20-24 — eğitim / metot seçimi')
add(T,E,['EPA Method 323'],'Formaldehit için başka bir VOC yönteminin örnekleme koşulu doğrudan aktarılabilir mi?','Hayır; hedef analit, toplama kimyası ve metot kapsamı eşleştirilir.',['Evet, tüm organikler aynı tüple toplanır.','Evet, yalnız süreyi ikiye katlamak yeterlidir.','Evet, blank gereksizdir.'],'Formaldehit için doğrulanmış toplama ve analitik yöntem gerekir. Toplam organik karbon veya genel VOC yöntemi tek başına formaldehit yönteminin eşdeğeri değildir.','D39:4-8 — talimat / kavramsal')
add(T,E,['EPA Method 11'],'EPA Method 11’in H₂S ölçümü için metot seçerken hangisi mutlaka kontrol edilir?','Kaynak türü ve metot kapsamına uygunluk',['Yalnız impingerlerin görünüşü','Yalnız cihazın markası','Her bacada aynı uygulanacağı varsayımı'],'Method 11’in kapsamı rafineri yakıt gazı bağlamını içerir. Bir yöntemin hedef bileşiği ölçmesi, her baca gazına koşulsuz uygulanabileceği anlamına gelmez.','D04:1 — birincil kapsam')

T='Toz, hız ve gaz ölçümleri'
add(T,E,['EPA Method 5','EPA Method 17'],'EPA Method 5 ile Method 17 karşılaştırmasında temel fark hangi ekipmanla ilgilidir?','Filtrenin baca içi / dışı konumu',['DGM’nin hiç kullanılmaması','Bütün tozun çözünmüş gaz sayılması','Her ikisinin yalnız imisyon ölçmesi'],'Method 17 baca içi filtre yaklaşımıdır. Filtre konumunu değiştirip diğer bütün sıcaklık, kapsam ve geri kazanım koşullarını aynı varsaymak doğru değildir.','Ana katalog: EPA Method 5 / Method 17 — kavramsal kapsam')
add(T,E,['EPA Method 5'],'İzokinetik toz örneklemesinde tek bir sabit debi bütün bacalara neden atanamaz?','Gerekli debi baca hızı, nozül ve gaz koşullarına bağlıdır.',['Süre hiçbir zaman ölçülmediği için','Hacim yerine yalnız saat yazıldığı için','Filtre rengi debiyi belirlediği için'],'Temsili partikül alımı, nozül giriş hızının yerel gaz hızıyla ilişkisine bağlıdır. Debi hesabında sıcaklık, basınç ve nem koşulları da tutarlı tutulur.','D09:8-11; ortak saha esasları: izokinetik')
add(T,E,['TS EN 13284-1','ISO 12141'],'TS EN 13284-1 ve ISO 12141 hangi tür çalışmayla ilişkilidir?','Düşük toz derişiminde manuel gravimetrik ölçüm',['Yalnız pasif gaz tüpü','Yalnız dioksin toksisite analizi','Yağış miktarı ölçümü'],'Bu metotlar düşük toz derişimindeki manuel gravimetrik ölçüm bağlamındadır. Metot seçimi kaynak ve çalışma aralığıyla doğrulanmalıdır; sayısal koşullar özdeş varsayılmaz.','D31:1-4; ana katalog TS EN 13284-1 — kapsam')
add(T,E,['TS ISO 9096'],'TS ISO 9096’da örneklenen toz ile prob/nozül birikintileri için doğru yaklaşım nedir?','Metodun geri kazanım kapsamına göre birlikte izlenir.',['Filtre dışındaki birikintiler her zaman atılır.','Sadece dış yüzey tozu toplanır.','Yıkama gerekip gerekmediği rastgele seçilir.'],'Numune yalnız görünen filtre lekesinden ibaret değildir. Numuneye temas eden yüzeylerin geri kazanımı ve blank etkisi seçilen gravimetrik metoda göre değerlendirilir.','Ana katalog TS ISO 9096; ortak saha esasları: geri kazanım')
add(T,E,['TS EN ISO 16911','TS ISO 10780','EPA Method 2'],'Pitot ile hız hesabında hangi veri grubu anlamlıdır?','Diferansiyel basınç, Pitot katsayısı ve gaz yoğunluğunu belirleyen koşullar',['Yalnız tarih ve operatör adı','Yalnız impingerin rengi','Sadece filtrenin gramajı'],'Pitot basınç farkı hıza çevrilirken katsayı ve gaz yoğunluğu gerekir. Bir sensörün anlık okuması, diğer gerekli koşullar olmadan güvenilir hacimsel debi vermez.','D29; D50-D51; ortak saha esasları: hız')
add(T,E,['TS EN ISO 16911','TS ISO 10780','EPA Method 2'],'Hacimsel baca debisi için ortalama hız dışında hangi temel büyüklük gerekir?','Baca kesit alanı',['Blank kabının rengi','Ses seviyesi','Filtrenin gözenek sayısının karesi'],'Aynı referans koşullarında hacimsel debi hız ile kesit alanının çarpımıyla ilişkilidir. Birimler ve hız profilinin temsil ediciliği kontrol edilir.','D29; ortak saha esasları: hız / debi')
add(T,E,['TS ISO 12039','TS EN 14789','TS EN 14792','TS EN 15058'],'Yanma gazı ölçümünde sıfır/span kontrolünün amacı nedir?','Sistemin ölçüm cevabı ve kaymasını kontrol etmek',['Baca alanını ölçmek','İmpinger sırasını otomatik belirlemek','Toz filtresini sabit tartıma getirmek'],'Sıfır/span ve drift kontrolleri gaz ölçüm sisteminin cevabına yöneliktir. Kabul sınırları gaz ve metot için ayrı kontrol edilir.','D30; ortak saha esasları: gaz analizörleri')
add(T,E,['TS ISO 7935'],'SO₂ ölçümünde girişim ve kalibrasyon neden ayrı değerlendirilir?','Doğru kalibrasyon, bütün girişimlerin yok olduğunu kanıtlamaz.',['Kalibrasyon yapılınca numune hattı gereksizdir.','Girişim yalnız filtre tartımını etkiler.','Her SO₂ yöntemi aynı kimyayla çalışır.'],'Ölçüm sistemi başka bileşenlere çapraz cevap verebilir. Kalibrasyonun geçerli olması, seçicilik ve saha gaz matrisi kontrolünü ortadan kaldırmaz.','Ana katalog: TS ISO 7935; ortak saha esasları')
add(T,E,['TS EN 12619','EPA Method 25A'],'FID ile toplam organik karbon sonucundan tek bir VOC bileşiğinin derişimi doğrudan çıkarılabilir mi?','Hayır; toplam cevap, tekil bileşik türlemesi değildir.',['Evet, her zaman benzen sonucudur.','Evet, her organik aynı yanıt faktöründedir.','Evet, gaz hacmi bilinmeden çıkarılır.'],'TOC/FID toplam cevap ölçerken tekil bileşik analizi başka bir hedef ve analitik ayrım gerektirir. Kalibrasyon gazı ve karbon eşdeğeri de önemlidir.','D24; D45; ortak saha esasları: VOC / TOC')
add(T,E,['TS EN 13649','TSE CEN/TS 13649'],'Aktif adsorban tüpünde kırılma neyi anlatır?','Hedef bileşiğin ön toplama bölümünü geçerek kayba / arka bölüme ulaşmasını',['Tüp etiketinin yırtılmasını','Pompa saatinin durmasını','DGM sıcaklığının her zaman sıfır olmasını'],'Adsorban kapasitesi, nem, sıcaklık ve debi yakalama verimini etkiler. Arka bölüm kontrolü ve doğrulanmış hacim/debi aralığı bu nedenle önemlidir.','D37; ortak saha esasları: filtre / adsorban ve VOC')
add(T,E,['TS 9503'],'Bacada islilik değerlendirmesi ile gravimetrik toz derişimi için hangisi doğrudur?','Farklı ölçülen büyüklüklerdir; otomatik birbirine dönüştürülmez.',['Aynı birim ve sonuçtur.','İslilik daima µg/m³ olarak tartılır.','Filtre koyuluğu bütün metallerin kütlesini verir.'],'Optik / karşılaştırmalı islilik göstergesi, tartılan toz kütlesi değildir. Sonuç ve yöntem kapsamı doğru adlandırılmalıdır.','D35; ana katalog: TS 9503 — kavramsal')
add(T,E,['ISDL / MID'],'ISDL planlamasında gerekli gaz hacmi hangi verilere bağlıdır?','Analitik tayin sınırı, numune son hacmi ve hedef raporlama derişimi',['Yalnız kullanıcı adı','Yalnız impinger dış çapı','Yalnız saha sıcaklığının işareti'],'Sıvıdaki tayin sınırı ile gazdaki hedef derişim aynı birim değildir. Hedef hacim hesaplandıktan sonra metot asgari süre/hacim koşulları da ayrıca sağlanır.','D11; ortak saha esasları: hedef tayin sınırı')

T='Ölçüm yeri, girdap ve uygunsuzluk'
add(T,E,['TS EN 15259','EPA Method 1'],'EPA Method 1 null tekniğinde açılar +30° ve −30° ise ortalama |α| kaçtır?','30°',['0°','60°','15°'],'Mutlak değerler ortalanır: (30+30)/2=30°. İşaretli açıları toplamak girdabı yanlış biçimde sıfır gösterir.','EPA Method 1 §11.4; resmi EPA 28.04.2020 metni')
add(T,E,['EPA Method 1'],'EPA Method 1 §11.4’te ortalama mutlak açı tam 20° ise hangi ifade doğrudur?','Bu maddede >20° eşiği aşılmamıştır; diğer koşullar ayrıca değerlendirilir.',['Mutlaka bütün saha uygundur.','20° ve üstü daima aynı maddede reddir.','Sıfır açı sayılır.'],'Kaynak ifadesi 20°’den büyük ortalamadır. Eşik değerlendirmesi tam hassasiyetle yapılır; tek açı testi bütün saha uygunluğunu kanıtlamaz.','EPA Method 1 §11.4')
add(T,E,['EPA Method 1'],'Açısı ölçülemeyen bir travers noktasına ortalama için 0° yazılmalı mı?','Hayır; eksik ölçüm sıfır ölçüm değildir.',['Evet, sonuç daha dengeli olur.','Evet, yalnız negatif açı yerine','Evet, bütün noktalara 0 yazılabilir.'],'0° ancak geçerli null ölçümünün sonucudur. Eksik noktayı sıfırla doldurmak ortalamayı düşürür ve ham veriyi değiştirir.','EPA Method 1 §11.4; ortak saha esasları: izlenebilirlik')
add(T,E,['EPA Method 1'],'EPA null tekniğinde manometre başlangıcında ne yapılır?','Terazileme, sıfırlama ve bağlantı / kaçak kontrolü',['Yalnız pompayı maksimuma çıkarma','Şişelere asit ekleyip açı varsayma','Pitot deliklerini bantla kapatma'],'Manometre sıfırı ve bağlantı kaçağı yanlışsa null açısı da yanlış bulunabilir. Temel cihaz hazırlığı açı hesabından önce gelir.','EPA Method 1 §11.4.2')
add(T,E,['TS EN 15259','EPA Method 1'],'Girdap veya ters akış saptanınca yalnız nokta sayısını artırmak ne sağlar?','Tek başına uygunluk sağlamaz; geçerli alternatif prosedür gerekir.',['Her standarda otomatik uygunluk sağlar.','Kalibrasyon ihtiyacını kaldırır.','Metot sürümünü değiştirmiş sayılır.'],'Yer ve akış uygunsuzluğu, yalnız daha çok veri toplamakla ortadan kalkmaz. Alternatif yöntemin uygulanabilirliği ve gereken onaylar kontrol edilir.','Ortak saha esasları: uygunsuz ölçüm yeri')
add(T,E,['TS EN 15259','EPA Method 1'],'Baca krokisinde bozucu etki mesafelerini kaydederken ne mutlaka belirgin olmalıdır?','Akış yönü ve ölçüm düzleminin bozucuya göre konumu',['Yalnız tesis logosu','Yalnız kovanın rengi','Sadece ölçüm gününün haftası'],'Akışa göre öncesi/sonrası belirsiz bir mesafe notu farklı yorumlanabilir. Kroki, kesit ve bozucu etkiler birlikte kaydedilir.','D21; ortak saha esasları: port / travers')
add(T,E,['TS EN 15259','EPA Method 1'],'Erişilemeyen travers noktası için doğru işlem nedir?','Eksik erişimi kaydetmek ve metotla uyumlu çözümü değerlendirmek',['Noktayı kayıt bırakmadan silmek','Yakın noktayı iki kez yazıp gizlemek','Rastgele hız üretmek'],'Nokta planı kesiti temsil etmek içindir. Erişim problemi kayıt altına alınmadan nokta azaltılması temsil kabiliyetini ve değerlendirmeyi bozar.','Ortak saha esasları: ölçüm düzlemi / sapmalar')
add(T,E,['TS EN 15259'],'EPA açı kabul eşiği EN/ISO metoduna otomatik uygulanabilir mi?','Hayır; ölçülen açı tanımı ve standardın kendi kriteri kontrol edilir.',['Evet, bütün sayılar evrenseldir.','Yalnız cihaz aynı renkteyse','Yalnız bütün açılar pozitifse'],'Farklı metotların açı tanımı, nokta bazlı veya ortalama kriterleri ve ekipmanı farklı olabilir. Sadece aynı derece birimini görmek eşdeğerlik değildir.','Ortak saha esasları: girdap / metot seçimi')
add(T,E,['EPA Method 2'],'Pitot deliklerinde tıkanma veya hortumda su varsa önce ne yapılır?','Ölçümü etkileyen arızayı giderip uygun doğrulamayı yapmak',['Hızı otomatik %10 artırmak','Eksik basıncı rastgele tamamlamak','Sadece sonuç birimini değiştirmek'],'Basınç iletimi bozulduğunda okuma güvenilmez olabilir. Sayısal bir düzeltme uydurmak yerine cihaz durumu ve etkilenen ölçüm aralığı değerlendirilir.','Ortak saha esasları: kalibrasyon / uygunsuzluk')
add(T,E,[],'Güvensiz platform veya erişim koşulunda doğru yaklaşım nedir?','Güvenli çalışma koşulu sağlanmadan başlamamak',['Süreyi kısaltıp yine ölçmek','Yalnız fotoğraf çekip her koşulda sürdürmek','Bütün noktalara ulaşılabildiğini varsaymak'],'Ölçüm kalitesi güvenli erişimin yerine geçmez. Saha sorumlusuyla risk ve gerekli önlem değerlendirilmeli; çalışan tehlikeye maruz bırakılmamalıdır.','Ortak saha esasları: saha güvenliği')

T='Birim, hacim ve hesap'
add(T,O,[],'Aynı koşullara ait sabit 2 L/dk debiyle 30 dk çekiş hacmi kaç litredir?','60 L',['15 L','0,067 L','600 L'],'V=Q×t=2×30=60 L. Bu çarpım yalnız aynı koşullardaki debi için geçerlidir; farklı gaz referanslarına otomatik geçiş değildir.','Ortak saha esasları: debi / hacim')
add(T,O,[],'1 ft³, kaynak gaz koşulları korunarak yaklaşık kaç litredir?','28,31685 L',['2,831685 L','0,0283 L','1000 L'],'1 ft=0,3048 m tanımından 1 ft³=0,028316846592 m³ elde edilir. Bu geometrik dönüşüm sıcaklık ve basıncı değiştirmez.','Birim dönüştürücü: ft³ → L')
add(T,O,[],'1 cfm kaynak koşullarında yaklaşık hangi debidir?','28,31685 L/dk',['28,31685 L/s','1 L/dk','1000 L/dk'],'cfm ft³/dakika demektir. Hacim birimi dönüştürülürken dakika aynı kalır; saniyeye geçiş ayrıca 60 katsayısı gerektirir.','Birim dönüştürücü: cfm → L/dk')
add(T,O,[],'68 °F kaç °C’dir?','20 °C',['68 °C','37,8 °C','−20 °C'],'C=(F−32)×5/9 olduğundan (68−32)×5/9=20 °C. Yalnız 5/9 ile çarpmak ofseti atlar; sıcaklık dönüşümü hacim dönüşümü gibi tek bir çarpanla yapılmaz.','Birim dönüştürücü: °F → °C')
add(T,O,[],'Sayaç başlangıcı 1,250 m³, bitişi 1,870 m³ ise ham fark nedir?','0,620 m³',['3,120 m³','1,496 m³','620 m³'],'Ham sayaç hacmi bitiş eksi başlangıçtır. Bu değer henüz sıcaklık, basınç ve kuru/yaş baza göre düzeltilmiş hacim olarak adlandırılmaz.','Ortak saha esasları: DGM / referans hacmi')
add(T,O,[],'0,5 mg kaç µg’dır?','500 µg',['5 µg','50 µg','0,0005 µg'],'1 mg=1000 µg olduğundan 0,5×1000=500 µg. Derişim hesabından önce kütle birimleri eşlenmelidir.','Ortak saha esasları: birim tutarlılığı')
add(T,O,[],'600 L kaç m³’tür?','0,600 m³',['600 000 m³','6 m³','0,006 m³'],'1 m³=1000 L, dolayısıyla 600/1000=0,600 m³. Hacim birimini değiştirmek referans sıcaklığını ve basıncını değiştirmek değildir.','Birim dönüştürücü / ortak saha esasları')
add(T,O,[],'Gaz derişimindeki kuru ve yaş baz neden ayrı belirtilir?','Su buharının hacme dahil edilmesi sonucu değiştirir.',['Yalnız yazı tipi değişir.','Kuru baz her zaman sayaç hacmidir.','Yaş bazın birimi daima gramdır.'],'Aynı kirletici kütlesi, su dahil ve su hariç farklı hacimlere bölünebilir. Baz belirtilmeden sonuçlar doğrudan karşılaştırılmaz.','Ortak saha esasları: nem / referans koşulları')
add(T,O,[],'İzokinetik çekiş sırasında debi değişiyorsa tek başlangıç debisi × süre yeterli midir?','Hayır; gerçek sayaç farkı veya uygun aralıklı hacimler değerlendirilir.',['Evet, tüm değişimler yok sayılır.','Yalnız en yüksek debi kullanılır.','Yalnız en düşük debi kullanılır.'],'Değişken debide hacim debinin zamana göre toplamıdır. Tek bir anlık debi tüm örnekleme koşullarını temsil etmez.','Ortak saha esasları: debi / hacim')
add(T,O,[],'Geleneksel 1 inHg yaklaşık kaç hPa’dır?','33,8639 hPa',['3,38639 hPa','1013,25 hPa','249,09 hPa'],'Bu araç geleneksel cıva sütunu tanımını kullanır. Su sütunu ile cıva sütunu aynı dönüşüm katsayısına sahip değildir; cihaz referansı kontrol edilir.','Birim dönüştürücü: inHg → hPa')

T='Kalite, numune ve teslim'
for prompt,right,wrong,explanation in [
 ('Saha blankı ile reaktif blankı için hangisi doğrudur?','Farklı bulaşma yollarını kontrol edebilirler.',['Her zaman aynı işlemdir.','İkisi de zorunlu olarak baca gazı çeker.','Reaktif blankı yalnız debi kalibrasyonudur.'],'Blank türleri kontrol ettikleri aşamaya göre ayrılır. Bir blankın varlığı diğer kontrolün otomatik yerine geçtiğini göstermez.'),
 ('Numune etiketinde hangi kimlik grubu temel önemdedir?','Tesis/nokta, tarih-saat, metot ve fraksiyon kimliği',['Yalnız numunecinin adı','Yalnız sıvının rengi','Sadece cihaz fiyatı'],'Teslim zinciri numunenin nereden, ne zaman ve hangi fraksiyon olarak alındığını takip edebilmelidir. Aynı bacanın farklı yıkamaları karıştırılmamalıdır.'),
 ('Metotta saklama süresi bulunamadığında ne yapılır?','Geçerli kaynak ve laboratuvar koşulu doğrulanır.',['Her zaman 48 saat atanır.','Bütün numunelere 6 ay verilir.','Süre alanı dolsun diye rastgele sayı yazılır.'],'Belirsiz alanı varsayılan sayıyla doldurmak bir gerekliliği yanlış belirlemek olabilir. Eksik kaynak bilgisi açıkça izlenmeli ve tamamlanmalıdır.'),
 ('Numune kabındaki sıvı seviyesinin işaretlenmesi ne işe yarar?','Taşıma sırasında sıvı kaybı / sızıntı kontrolüne',['Numunenin kimyasal türünü tek başına bulmaya','Baca hızını hesaplamaya','T90 belirlemeye'],'Seviye izi teslimde olası hacim kaybının değerlendirilmesini destekler. Etiket ve kap kontrolüyle birlikte kullanılır.'),
 ('Kalibrasyon belgesinin olması neyi ortadan kaldırmaz?','Saha işlev, sıfır, kaçak ve gerekli ara kontrollerini',['Bütün kayıt ihtiyacını kaldırır.','Operatör eğitimini gereksiz yapar.','Yanlış bağlantıyı otomatik düzeltir.'],'Kalibrasyon belirli koşullarda ölçüm izlenebilirliği sağlar. Sahadaki bağlantı, arıza veya drift ayrıca kontrol edilmelidir.'),
 ('Ölçümde proses duruşu olursa doğru kayıt nedir?','Duruş zamanı, süre ve etkilenen örnekleme aralığı',['Kesintiyi gizleyip kesintisiz yazmak','Başlangıç saatini değiştirmek','Sonucu uygun bir sayıya yuvarlamak'],'Proses koşulu numunenin temsil ediciliğini etkiler. Olay kaydı, ilgili metodun durdurma/tekrar ve raporlama değerlendirmesini mümkün kılar.'),
 ('Başlangıç dolum hacmi ile laboratuvar son hacmi aynı alan mıdır?','Hayır; farklı aşamaların miktarlarıdır.',['Evet, her zaman eşittir.','Son hacim çekilen gaz hacmidir.','Dolum hacmi sadece DGM farkıdır.'],'Dolum, yıkama ve son hacim ayrı kaydedilir. Analitik son hacim gaz örnekleme hacmi değildir ve birbirine kopyalanamaz.'),
 ('Aynı ölçüm serisinde aynı etiketi iki numuneye vermek neden sakıncalıdır?','Fraksiyon ve sonuç izlenebilirliği kaybolabilir.',['Yalnız yazıcı mürekkebi azalır.','Sonuç mutlaka iki kat doğru olur.','Hiçbir etkisi yoktur.'],'Benzersiz kimlikler filtre, kartuş, çözelti ve blankın doğru sonuçla eşlenmesini sağlar. Tekrarlı etiket, teslim zincirini belirsizleştirir.'),
 ('Saklamada yalnız sıcaklığı kontrol etmek yeterli midir?','Hayır; kap, kapak, ışık, süre ve bulaşma da kontrol edilir.',['Evet, diğer her şey önemsizdir.','Yalnız kap renginin aynı olması yeterlidir.','Sıcaklık bilinirse etiket gerekmez.'],'Numune bütünlüğü çok sayıda etkene bağlıdır. Isı kontrolü yanlış kap malzemesi veya açık kapaktan kaynaklanan kaybı tek başına önlemez.'),
 ('Saha verisi kabul sınırını aşınca ne yapılır?','Metodun izin verdiği düzeltme, tekrar veya ret yolu değerlendirilir.',['Sınırın altına rastgele sayı yazılır.','Ham veri silinir.','Yalnız sonuç başlığı değiştirilir.'],'Uygunsuzluk gerçek verisiyle korunur. Düzeltme yalnız yöntem izin veriyorsa, gerekçesi ve etkisi izlenebilir şekilde uygulanabilir.'),
]: add(T,O,[],prompt,right,wrong,explanation,'Ortak saha esasları: kalite / numune / teslim')

T='İmisyon — PM10 ve PM2,5'
P=['TS EN 12341']
add(T,I,P,'EN 12341:2023 hangi ortamda PM kütle derişimi ölçümünü tarif eder?','Ortam havasında',['Yalnız baca içinde izokinetik','Yalnız içme suyunda','Yalnız çöken toz kabında'],'EN 12341 ortam havası PM10/PM2,5 gravimetrik yöntemidir. Baca toz metotlarının nozül ve travers kuralları doğrudan bu yönteme aktarılmaz.','D23:8')
add(T,I,P,'EN 12341:2023 anma debisi hangisidir?','2,3 m³/saat',['2,3 L/dk','21 L/dk','30 m³/dk'],'Kaynak 2,3 m³/saat verir; yaklaşık 38,33 L/dk karşılığıdır. Saat ve dakika birimlerini karıştırmak debiyi 60 kat değiştirebilir.','D23:8')
add(T,I,P,'EN 12341:2023 anma örnekleme süresi hangisidir?','24 saat',['Her durumda 30 dakika','2 dakika','7 saniye'],'24 saat anma süresidir. Gerçek süre, kesinti ve cihaz durum bayrakları ayrıca kaydedilir; anma süre gerçek geçerliliğin otomatik kanıtı değildir.','D23:8,25')
add(T,I,P,'2,3 m³/saat anma debisi 24 saat korunursa teorik ortam hacmi kaçtır?','55,2 m³',['5,52 m³','552 m³','24 m³'],'2,3×24=55,2 m³ hesaplanır. Gerçek sonuçta cihazın ölçtüğü geçerli debi ve süre esas alınır; bu sayı otomatik doldurulmaz.','D23:8; aynı koşullarda Q×t hesabı')
add(T,I,P,'EN 12341’de raporlanan PM hacim bazının özelliği nedir?','Giriş yakınındaki örnekleme anı ortam koşullarındaki hava hacmi',['Her zaman 0 °C kuru Nm³','Her zaman baca şartları','Daima 20 °C’de baca gazı'],'Kaynak kapsamı hacmi giriş yakınındaki ortam koşullarında tanımlar. Standart hacim etiketi eklemek metot bazını değiştirebilir.','D23:8')
add(T,I,P,'PM10 ve PM2,5 başlığı seçiminde ne önemlidir?','Hedef fraksiyon ve başlığın doğrulanmış debisi',['Yalnız başlık renginin aynı olması','Her iki başlığın da tüm debilerde aynı kesim yapması','Baca nozülü çapının aynen kullanılması'],'Boyut ayırmanın performansı başlık tasarımı ve debiye bağlıdır. Hedef PM fraksiyonu için doğru başlık/örnekleyici eşleşmesi gerekir.','D23:8,14-21 — ekipman kapsamı')
add(T,I,P,'EN 12341:2023 ön koşullandırma sıcaklık ve nem aralığı hangisidir?','19–21 °C ve %45–50 bağıl nem',['105 °C ve %0 nem','0–5 °C ve %100 nem','Ortam neyse o'],'Filtreler tartım öncesi belirli iklim koşullarında dengeye getirilir. Baca toz filtre kurutma sıcaklıklarını bu koşula kopyalamak doğru değildir.','D23:30')
add(T,I,P,'EN 12341:2023 ilk ön tartımdan önce en az ne kadar koşullandırma tarif eder?','48 saat',['48 dakika','5 dakika','Süre şartı yoktur.'],'Arşiv §6.3 en az 48 saat koşullandırma ve ardından ilk tartımı belirtir. İkinci tartım ve kabul kuralları da ayrı uygulanır.','D23:30')
add(T,I,P,'EN 12341 saha blankı için kasetteki en az bir filtre nasıl kullanılır?','Örnekleme yapılmadan kasette kalır.',['Bütün süre boyunca aktif çekiş yapılır.','Filtre kasetten çıkarılıp açıkta bırakılır.','Numune filtreleriyle etiketleri birleştirilir.'],'§6.4.2 en az bir örneklenmeyen filtrenin saha blankı olarak kasette bulunmasını tarif eder. Blank, aktif numune filtresi gibi gaz çekmez.','D23:31')
add(T,I,P,'Örneklenmiş PM filtrelerinin taşınmasında hangi amaç birlikte gözetilir?','Kirlenme, aşırı ısınma, uçucu kaybı ve yoğuşmayı önlemek',['Filtreyi güneşte kurutmak','Tartım öncesi filtre yüzeyini fırçalamak','Kaba isimsiz koymak'],'Kapalı/yalıtımlı koruma ve uygun sıcaklık yönetimi gerekir. Soğutma uygulanırken filtre üzerinde yoğuşmaya da yol açılmamalıdır.','D23:31')

T='İmisyon — çöken toz ve pasif örnekleme'
P=['TS 2341','TS 2342']
add(T,I,P,'Çöken toz hesabında temel örnekleme büyüklükleri hangileridir?','Toplanan kütle, toplama alanı ve maruziyet süresi',['Yalnız DGM hacmi','Yalnız baca nozül hızı','Yalnız impinger sayısı'],'Çökelme akısı alan ve zaman başına kütleyle ilişkilidir. Pompayla çekilmiş hava hacmini payda yapmak farklı bir ölçüm yaklaşımını karıştırır.','D44:5; ortak saha esasları: çöken toz')
add(T,I,P,'Çöken toz kabı için gerçek maruziyet süresi neden yazılır?','Alan-zaman başına sonucun paydasını etkiler.',['Yalnız cihazın garantisini etkiler.','Süre her koşulda 30 kabul edilebilir.','Yağmur varsa süre tamamen silinir.'],'Gerçek başlangıç ve bitiş, toplama süresini izlenebilir kılar. Eksik/kayıp numune veya farklı takvim süresi otomatik sabit günle gizlenmez.','D44:4-5; ortak saha esasları')
add(T,I,P,'Çöken toz kabının devrilmesi veya kaybolması ne gerektirir?','Olay ve geçerlilik etkisinin kaydını',['Kütleyi komşu kaptan kopyalamayı','Kabı hiç kurulmamış sayıp kaydı silmeyi','Rastgele bir tartım üretmeyi'],'Numune bütünlüğünü etkileyen olaylar değerlendirmeye dahil edilir. Kayıp verinin başka noktayla doldurulması ham ölçüm değildir.','Ortak saha esasları: imisyon saha olayları')
add(T,I,P,'Çöken toz numunesinde kap duvarına yapışan materyal nasıl ele alınır?','Metodun nicel geri kazanım adımlarına göre değerlendirilir.',['Her zaman tamamen atılır.','Yalnız renk değerlendirilir.','Açık havada üflenerek temizlenir.'],'Numune toplama yüzeyindeki birikim, yöntem kapsamına göre geri alınır. Yıkamada eklenen miktar ve yabancı cisim işlemleri izlenebilir tutulur.','D44:6 — talimat aktarımı')
P=['Pasif Örnekleme']
add(T,I,P,'Pasif difüzyon tüpünde pompa debisi girilir mi?','Hayır; doğrulanmış alım hızı ve maruziyet koşulları kullanılır.',['Evet, her tüpe 21 L/dk','Evet, baca izokinetik debisi','Evet, her koşulda 100 L/dk'],'Pasif örnekleme pompaya dayanmaz. Alım hızı, tüp ve hedef bileşiğe özgü tanımdır; aktif çekiş debisiyle aynı büyüklük gibi kullanılmaz.','D46; ortak saha esasları: pasif tüp')
add(T,I,P,'Pasif tüpün açılma ve kapanma saatleri neden kaydedilir?','Gerçek maruziyet süresini belirlemek için',['DGM farkını hesaplamak için','Nozül çapını seçmek için','Girdap açısını ölçmek için'],'Maruziyet süresi pasif örneklemenin temel girdisidir. Etiket ve zaman hatası, ölçülen kütlenin yanlış süreyle ilişkilendirilmesine yol açabilir.','D46:4-5')
add(T,I,P,'Pasif tüp için saklama ve analiz süresi nasıl seçilir?','Tüp / hedef bileşik ve geçerli üretici-metot koşullarına göre',['Bütün tüplere evrensel 6 ay','Bütün tüplere 48 dakika','Sadece tüpün rengine göre'],'Farklı adsorban ve hedef gazlar aynı stabiliteye sahip değildir. Eski bir talimattaki tek süre bütün tüplere koşulsuz uygulanmaz.','D46:5; ortak saha esasları: saklama')
add(T,I,P,'Pasif tüp için sıcaklık, nem ve rüzgâr neden kaydedilir?','Uygulanabilirlik ve alım performansını etkileyebilir.',['Yalnız fotoğrafın güzel çıkması için','Baca alanı bunlardan hesaplandığı için','Hiçbir etkisi yoktur.'],'Tüpün doğrulanmış kullanım aralığı ve koruyucu kap koşulları değerlendirilir. Çevresel kayıt, maruziyetin uygunluğunu izlemeyi sağlar.','D46:5')
add(T,I,['TS EN 12341','TS 2341','Pasif Örnekleme'],'İmisyon noktasında çevre kaynak ve engellerin kaydı neye hizmet eder?','Ölçümün temsil ettiği ortamın yorumlanmasına',['Bütün sonuçların otomatik düzeltilmesine','Numunenin adının gereksiz olmasına','Konsantrasyonu sıfıra eşitlemeye'],'Yakın kaynak, engel ve meteoroloji ölçümün temsil ediciliğini etkiler. Bunları kaydetmek, bir katsayı uydurup sonucu değiştirme yetkisi vermez.','Ortak saha esasları: imisyon / yerleşim / meteoroloji')
add(T,I,['TS EN 12341','TS 2341','Pasif Örnekleme'],'Emisyon baca metodu ile imisyon metodu neden ayrı seçilir?','Ölçülen ortam, örnekleme ilkesi ve sonuç bazları farklıdır.',['Yalnız uygulama logosu değiştiği için','İmisyonda hiçbir kalite kontrol olmadığı için','Emisyon sonuçları her zaman imisyon yerine geçtiği için'],'Baca içindeki kütlesel çıkış ile ortam havası maruziyeti farklı hedeflerdir. Aynı kirleticinin adı örnekleme yöntemlerini özdeş yapmaz.','Ortak saha esasları: emisyon / imisyon ayrımı')

add('Yanma gazı standartları',E,['TS EN 14789'],'TS EN 14789 hangi gazın referans ölçüm yöntemiyle ilişkilidir?','O₂',['CO','NOₓ','PM2,5'],'Oksijen ölçümü, diğer kirleticilerin referans oksijene göre değerlendirilmesinde de gerekli olabilir. O₂ ölçümü ile düzeltme hesabı farklı aşamalardır.','Ana katalog: TS EN 14789 — kapsam')
add('Yanma gazı standartları',E,['TS EN 14792'],'TS EN 14792 hangi gaz grubuyla ilişkilidir?','NOₓ',['CO','HCl','PAH'],'Azot oksitleri için kullanılan standart ile CO ve HCl yöntemleri farklı hedef ve ölçüm ilkelerine sahiptir. Kalibrasyon ve girişim kontrolleri doğru gaz metoduna göre seçilir.','Ana katalog: TS EN 14792 — kapsam')
add('Yanma gazı standartları',E,['TS EN 15058'],'TS EN 15058 hangi bileşiğin ölçümüyle ilişkilidir?','CO',['O₂','HF','PCDD/F'],'Karbonmonoksit yöntemi toplam organik karbon veya oksijen yöntemi değildir. Parametre kodu, cihazın ölçüm kanalı ve raporlanan birim eşleştirilmelidir.','Ana katalog: TS EN 15058 — kapsam')
add('İmisyon — hesap ve kayıt',I,['TS 2341'],'10 mg çöken toz, 0,1 m² alanda 10 günde toplanmışsa (blank düzeltmesi sonrası) akı kaçtır?','10 mg/(m²·gün)',['1 mg/(m²·gün)','100 mg/(m²·gün)','1000 mg/(m²·gün)'],'Akı=10/(0,1×10)=10 mg/(m²·gün). Kütle, alan ve gün ayrı kontrol edilir; hava hacmi bu paydada yer almaz.','D44:5; boyutsal hesap')
add('İmisyon — hesap ve kayıt',I,['TS EN 12341'],'Blank ve tartım değerlendirmesi tamamlanmış 110,4 µg PM, 55,2 m³ ortam hacminden toplanırsa derişim kaçtır?','2 µg/m³',['0,5 µg/m³','20 µg/m³','6094,08 µg/m³'],'C=m/V=110,4/55,2=2 µg/m³. Hacmin ortam koşullarında olması ve geçerli ölçülen hacim kullanımı korunur.','D23:8; boyutsal hesap')
add('İmisyon — PM10 ve PM2,5',I,['TS EN 12341'],'EN 12341:2023’te numunenin 1 ay içinde tartım odasına alınması ifadesi nasıl yorumlanmalıdır?','Bu adıma özgü sınırdır; tüm parametrelere 1 ay analiz bekletme izni değildir.',['Bütün kimyasal numuneler 1 ay oda sıcaklığında kalabilir.','Tüm filtreler 1 ay dışarıda açık bekletilir.','Saklama koşulları artık uygulanmaz.'],'§6.4.3, gravimetrik analiz için tartım odasına alınmayı belirtir. Süreyi bağlamından çıkarıp bütün saklama ve analiz adımlarına genellemek doğru değildir.','D23:31')
add('İmisyon — hesap ve kayıt',I,['TS EN 12341','TS 2341','Pasif Örnekleme'],'Nokta koordinatı ile numune kimliğinin eşleşmesi neden kontrol edilir?','Sonucun doğru saha noktasına bağlanması için',['Sonucu otomatik düşürmek için','Bütün noktaları tek nokta saymak için','Sadece dosya boyutunu artırmak için'],'İmisyon değerlendirmesi konuma bağlıdır. Numune ile koordinatın karışması, doğru analiz edilmiş bir sonucun yanlış yer için yorumlanmasına yol açabilir.','Ortak saha esasları: meteoroloji / saha kayıtları')
add('İmisyon — hesap ve kayıt',I,['Pasif Örnekleme'],'Pasif tüpte yalnız toplam tutulan kütleyi bilmek ortam derişimini bulmaya her zaman yeterli midir?','Hayır; alım hızı, süre ve yöntem düzeltmeleri de gerekir.',['Evet, kütle daima derişimdir.','Evet, tüpün boyu tek başına yeterlidir.','Evet, yalnız baca çapı eklenir.'],'Kütle derişim değildir. Pasif tüpün bileşik ve koşullara özgü alım modeli, maruziyet ve blank değerlendirmesiyle birlikte kullanılır.','Ortak saha esasları: pasif örnekleme')

